
-- --------------------------------------------------------

--
-- Структура таблицы `oc_modification`
--

CREATE TABLE `oc_modification` (
  `modification_id` int(11) NOT NULL,
  `name` varchar(64) NOT NULL,
  `code` varchar(64) NOT NULL,
  `author` varchar(64) NOT NULL,
  `version` varchar(32) NOT NULL,
  `link` varchar(255) NOT NULL,
  `xml` text NOT NULL,
  `status` tinyint(1) NOT NULL,
  `date_added` datetime NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

--
-- Дамп данных таблицы `oc_modification`
--

INSERT INTO `oc_modification` (`modification_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(2, 'Export/Import Tool (V3.9) for Ocstore 2.x', 'Export/Import Tool (V3.9) for Ocstore 2.x', 'pasha.strus@gmail.com', '2.x-3.1', 'https://opencartforum.com/user/7225-pashast/', '<modification>\n	<name>Export/Import Tool (V3.9) for Ocstore 2.x</name>\n	<code>Export/Import Tool (V3.9) for Ocstore 2.x</code>\n	<version>2.x-3.1</version>\n	<author>pasha.strus@gmail.com</author>\n	<link>https://opencartforum.com/user/7225-pashast/</link>\n	<file path=\"admin/controller/common/menu.php\">\n		<operation error=\"skip\">\n			<search><![CDATA[$data[\'text_backup\'] = $this->language->get(\'text_backup\');]]></search>\n			<add position=\"after\"><![CDATA[\n		$data[\'text_export_import\'] = $this->language->get(\'text_export_import\');\n			]]></add>\n		</operation>\n		<operation error=\"skip\">\n			<search><![CDATA[$data[\'backup\'] = $this->url->link(\'tool/backup\', \'token=\' . $this->session->data[\'token\'],]]></search>\n			<add position=\"after\"><![CDATA[\n		$data[\'export_import\'] = $this->url->link(\'tool/export_import\', \'token=\' . $this->session->data[\'token\'], (version_compare(PHP_VERSION, \'2.2.0.0\') >= 0) ? true : \'SSL\');\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/language/*/common/menu.php\">\n		<operation error=\"skip\">\n			<search><![CDATA[$_[\'text_backup\']]]></search>\n			<add position=\"after\"><![CDATA[\n$_[\'text_export_import\']               = \'Export / Import\';\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/view/template/common/menu.tpl\">\n		<operation error=\"skip\">\n			<search><![CDATA[<li><a href=\"<?php echo $backup; ?>\"><?php echo $text_backup; ?></a></li>]]></search>\n			<add position=\"replace\"><![CDATA[<li><a href=\"<?php echo $backup; ?>\"><?php echo $text_backup; ?></a></li><li><a href=\"<?php echo $export_import; ?>\"><?php echo $text_export_import; ?></a></li>]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/controller/common/column_left.php\">\n		<operation error=\"skip\">\n			<search><![CDATA[if ($this->user->hasPermission(\'access\', \'tool/log\')) {]]></search>\n			<add position=\"before\"><![CDATA[\n			if ($this->user->hasPermission(\'access\', \'tool/export_import\')) {\n				$tool[] = array(\n					\'name\'	   => $this->language->get(\'text_export_import\'),\n					\'href\'     => $this->url->link(\'tool/export_import\', \'token=\' . $this->session->data[\'token\'], true),\n					\'children\' => array()		\n				);\n			}\n			]]></add>\n		</operation>\n	</file>\n	<file path=\"admin/language/*/common/column_left.php\">\n		<operation error=\"skip\">\n			<search><![CDATA[$_[\'text_backup\']]]></search>\n			<add position=\"after\"><![CDATA[\n$_[\'text_export_import\']             = \'Export / Import\';\n			]]></add>\n		</operation>\n	</file>\n</modification>\n', 1, '2017-02-05 13:23:35'),
(3, 'Local copy OCMOD by iSenseLabs', 'isensealabs_quickfix_ocmod', 'iSenseLabs', '1.3', 'http://isenselabs.com', '<modification>\r\n    <name>Local copy OCMOD by iSenseLabs</name>\r\n	<version>1.3</version>\r\n	<link>http://isenselabs.com</link>\r\n	<author>iSenseLabs</author>\r\n	<code>isensealabs_quickfix_ocmod</code>\r\n\r\n	<file path=\"admin/controller/extension/installer.php\">\r\n		<operation error=\"skip\">\r\n			<search ><![CDATA[\'url\'  => str_replace(\'&amp;\', \'&\', $this->url->link(\'extension/installer/ftp\', \'token=\' . $this->session->data[\'token\'],]]></search>\r\n			<add position=\"replace\"><![CDATA[\'url\'  => str_replace(\'&amp;\', \'&\', $this->url->link(\'extension/installer/localcopy\', \'token=\' . $this->session->data[\'token\'],]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[public function unzip() {]]></search>\r\n			<add position=\"before\"><![CDATA[			\r\n	public function localcopy() {\r\n		$this->load->language(\'extension/installer\');\r\n\r\n		$json = array();\r\n\r\n		if (!$this->user->hasPermission(\'modify\', \'extension/installer\')) {\r\n			$json[\'error\'] = $this->language->get(\'error_permission\');\r\n		}\r\n\r\n		if (VERSION == \'2.0.0.0\') {\r\n		    $directory = DIR_DOWNLOAD  . str_replace(array(\'../\', \'..\\\\\', \'..\'), \'\', $this->request->post[\'path\']) . \'/upload/\';\r\n		} else {\r\n		    $directory = DIR_UPLOAD  . str_replace(array(\'../\', \'..\\\\\', \'..\'), \'\', $this->request->post[\'path\']) . \'/upload/\';\r\n		}\r\n\r\n		if (!is_dir($directory)) {\r\n			$json[\'error\'] = $this->language->get(\'error_directory\');\r\n		}\r\n\r\n		if (!$json) {\r\n			// Get a list of files ready to upload\r\n			$files = array();\r\n\r\n			$path = array($directory . \'*\');\r\n\r\n			while (count($path) != 0) {\r\n				$next = array_shift($path);\r\n\r\n				foreach (glob($next) as $file) {\r\n					if (is_dir($file)) {\r\n						$path[] = $file . \'/*\';\r\n					}\r\n\r\n					$files[] = $file;\r\n				}\r\n			}\r\n\r\n			$root = dirname(DIR_APPLICATION).\'/\';\r\n\r\n			foreach ($files as $file) {\r\n				// Upload everything in the upload directory\r\n				$destination = substr($file, strlen($directory));\r\n\r\n				// Update from newer OpenCart versions:\r\n				if (substr($destination, 0, 5) == \'admin\') {\r\n					$destination = DIR_APPLICATION . substr($destination, 5);\r\n				} else if (substr($destination, 0, 7) == \'catalog\') {\r\n					$destination = DIR_CATALOG . substr($destination, 7);\r\n				} else if (substr($destination, 0, 5) == \'image\') {\r\n					$destination = DIR_IMAGE . substr($destination, 5);\r\n				} else if (substr($destination, 0, 6) == \'system\') {\r\n					$destination = DIR_SYSTEM . substr($destination, 6);\r\n				} else {\r\n					$destination = $root.$destination;\r\n				}\r\n\r\n				if (is_dir($file)) {\r\n					if (!file_exists($destination)) {\r\n						if (!mkdir($destination)) {\r\n							$json[\'error\'] = sprintf($this->language->get(\'error_ftp_directory\'), $destination);\r\n						}\r\n					}\r\n				}\r\n\r\n				if (is_file($file)) {\r\n					if (!copy($file, $destination)) {\r\n						$json[\'error\'] = sprintf($this->language->get(\'error_ftp_file\'), $file);\r\n					}\r\n				}\r\n			}\r\n		}\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}]]></add>\r\n		</operation>\r\n	</file>	\r\n</modification>\r\n', 1, '2017-02-16 22:35:29'),
(5, 'Testimonials Lite Back End', 'testimonials_lite_back_end', 'vanstudio.co.ua', '1.4.1', 'http://vanstudio.co.ua', '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<modification>\r\n    <code>testimonials_lite_back_end</code>\r\n    <name>Testimonials Lite Back End</name>\r\n    <version>1.4.1</version>\r\n    <author>vanstudio.co.ua</author>\r\n    <link>http://vanstudio.co.ua</link>\r\n    <file path=\"admin/controller/common/menu.php\">\r\n        <operation>\r\n            <search><![CDATA[return $this->load->view]]></search>\r\n            <add position=\"before\"><![CDATA[\r\n				$data[\'testimonial\'] = $this->url->link(\'testimonial/testimonial\', \'token=\' . $this->session->data[\'token\'], \'SSL\');\r\n            ]]></add>\r\n        </operation>\r\n    </file>\r\n    <file path=\"admin/view/template/common/menu.tpl\">\r\n        <operation>\r\n            <search><![CDATA[<li><a href=\"<?php echo $information; ?>\"><?php echo $text_information; ?></a></li>]]></search>\r\n            <add position=\"before\"><![CDATA[\r\n				<li><a href=\"<?php echo $testimonial; ?>\">Testimonials</a></li>\r\n            ]]></add>\r\n        </operation>\r\n    </file>\r\n    <file path=\"admin/controller/setting/setting.php\">\r\n        <operation>\r\n            <search><![CDATA[$data[\'captcha_pages\'] = array();]]></search>\r\n            <add position=\"after\"><![CDATA[\r\n				$data[\'captcha_pages\'][] = array(\r\n			    \'text\'  => \'Testimonials\',\r\n			    \'value\' => \'testimonial\'\r\n		        );\r\n            ]]></add>\r\n        </operation>\r\n    </file>\r\n</modification>', 1, '2017-03-09 12:35:42'),
(18, 'Simple One Page Checkout', 'Simple-One-Page-Checkout', 'opencart2x', '2', 'https://opencart2x.ru', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n	<name>Simple One Page Checkout</name>\n	<code>Simple-One-Page-Checkout</code>\n	<version>2</version>\n	<author>opencart2x</author>\n	<link>https://opencart2x.ru</link>\n	\n    <file path=\"catalog/controller/checkout/checkout.php\">\n        <operation error=\"skip\">\n            <search ><![CDATA[if (file_exists(DIR_TEMPLATE . $this->config->get(\'config_template\') . \'/template/checkout/checkout.tpl\')) {]]></search>\n			<add position=\"replace\" offset=\"4\"><![CDATA[\n			// a_vqmod_d_quickcheckout.xml\n			if($this->config->get(\'d_quickcheckout_status\')){\n				$template = \'d_quickcheckout\';\n			}else{\n				$template = \'checkout\';\n			}\n			\n			if (file_exists(DIR_TEMPLATE . $this->config->get(\'config_template\') . \'/template/checkout/\'.$template.\'.tpl\')) {\n				$template = $this->config->get(\'config_template\') . \'/template/checkout/\'.$template.\'.tpl\';\n			} else {\n				$template = \'default/template/checkout/\'.$template.\'.tpl\';\n			}\n			$this->response->setOutput($this->load->view($template, $data));]]>\n			</add>\n        </operation>\n    </file>\n    <file path=\"catalog/controller/checkout/checkout.php\">\n        <operation error=\"skip\">\n			<search><![CDATA[$this->response->setOutput($this->load->view(\'checkout/checkout\', $data));]]></search>\n			<add position=\"replace\"><![CDATA[\n			// a_vqmod_d_quickcheckout.xml\n			if($this->config->get(\'d_quickcheckout_status\')){\n				$template = \'d_quickcheckout\';\n			}else{\n				$template = \'checkout\';\n			}\n			\n			$this->response->setOutput($this->load->view(\'checkout/\'.$template, $data));]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/checkout/checkout.php\">\n		<operation>\n			<search ><![CDATA[$data[\'header\'] = $this->load->controller(\'common/header\');]]></search>\n			<add position=\"before\"><![CDATA[\n		if($this->config->get(\'d_quickcheckout_status\')){\n			$data[\'d_quickcheckout\'] = $this->load->controller(\'module/d_quickcheckout\');\n		}\n		]]></add>\n		</operation>\n    </file>\n    <file path=\"system/library/cart/tax.php\">\n		<operation error=\"skip\">\n			<search ><![CDATA[final class Tax {]]></search>\n			<add position=\"after\"><![CDATA[\n	// a_vqmod_d_quickcheckout.xml\n	public function clearRates(){\n		$this->tax_rates = array();\n	}\n			]]></add>\n		</operation>\n	</file>	\n	<file path=\"system/library/tax.php\">\n		<operation error=\"skip\">\n			<search><![CDATA[final class Tax {]]></search>\n			<add position=\"after\"><![CDATA[\n	// a_vqmod_d_quickcheckout.xml\n	public function clearRates(){\n		$this->tax_rates = array();\n	}\n			]]></add>\n		</operation>\n	</file>	\n</modification>', 1, '2019-06-03 18:42:40'),
(23, 'Opencart - Быстрый заказ for OpenCart 2.0.x, 2.1.x', '9638944527', 'Domus159@gmail.com', '3.0.1', 'http://xdomus.ru/opencart/uproshhennyj-zakaz-dlya-opencart-2-besplatno/', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\r\n<modification>\r\n	<code>9638944527</code>\r\n    <name>Opencart - Быстрый заказ for OpenCart 2.0.x, 2.1.x</name>\r\n    <version>3.0.1</version>\r\n    <author>Domus159@gmail.com</author>\r\n    <link>http://xdomus.ru/opencart/uproshhennyj-zakaz-dlya-opencart-2-besplatno/</link>\r\n    <file path=\"catalog/controller/common/header.php\">\r\n        <operation>\r\n            <search>\r\n				<![CDATA[\r\n					$data[\'telephone\'] = $this->config->get(\'config_telephone\');\r\n				]]>\r\n			</search>\r\n            <add position=\"after\">\r\n				<![CDATA[\r\n					$data[\'buyoneclick_status\'] = $this->config->get(\'buyoneclick_status\');\r\n					$data[\'buyoneclick_status_category\'] = $this->config->get(\'buyoneclick_status_category\');\r\n\r\n					$data[\'buyoneclick_style_status\'] = $this->config->get(\'buyoneclick_style_status\');\r\n					$data[\'buyoneclick_validation_status\'] = $this->config->get(\'buyoneclick_validation_status\');\r\n					$data[\'buyoneclick_validation_type\'] = $this->config->get(\'buyoneclick_validation_type\');\r\n\r\n					$data[\'buyoneclick_ya_status\'] = $this->config->get(\'buyoneclick_ya_status\');\r\n					$data[\'buyoneclick_ya_counter\'] = $this->config->get(\'buyoneclick_ya_counter\');\r\n					$data[\'buyoneclick_ya_identificator\'] = $this->config->get(\'buyoneclick_ya_identificator\');\r\n\r\n					$data[\'buyoneclick_google_status\'] = $this->config->get(\'buyoneclick_google_status\');\r\n					$data[\'buyoneclick_google_category\'] = $this->config->get(\'buyoneclick_google_category\');\r\n					$data[\'buyoneclick_google_action\'] = $this->config->get(\'buyoneclick_google_action\');\r\n				]]>\r\n			</add>\r\n        </operation>\r\n    </file>\r\n    <file path=\"catalog/view/theme/*/template/common/header.tpl\">\r\n        <operation>\r\n            <search>\r\n				<![CDATA[\r\n					</head>\r\n				]]>\r\n			</search>\r\n            <add position=\"before\"><![CDATA[\r\n				<?php if ($buyoneclick_status || $buyoneclick_status_category) { ?>\r\n					<script src=\"catalog/view/javascript/buyoneclick.js\" type=\"text/javascript\"></script>\r\n					<?php if ($buyoneclick_validation_status) { ?>\r\n						<script src=\"catalog/view/javascript/jquery.mask.min.js\" type=\"text/javascript\"></script>\r\n						<script>\r\n							$(document).ready(function(){\r\n								$(\'#boc_phone\').mask(\'<?php echo $buyoneclick_validation_type; ?>\');\r\n							});\r\n						</script>\r\n					<?php } ?>\r\n					<?php if ($buyoneclick_ya_status || $buyoneclick_google_status) { ?>\r\n						<script>\r\n							function clickAnalytic(){\r\n								<?php if ($buyoneclick_ya_status) { ?>\r\n									yaCounter<?=$buyoneclick_ya_counter?>.reachGoal(\'<?=$buyoneclick_ya_identificator?>\');\r\n								<?php } ?>\r\n								<?php if ($buyoneclick_google_status) { ?>\r\n									ga(\'send\', \'event\', \'<?=$buyoneclick_google_category?>\', \'<?=$buyoneclick_google_action?>\');\r\n								<?php } ?>\r\n								return true;\r\n							}\r\n						</script>\r\n					<?php } ?>\r\n					<?php if ($buyoneclick_style_status) { ?><link href=\"catalog/view/theme/default/stylesheet/buyoneclick.css\" rel=\"stylesheet\"><?php } ?>\r\n				<?php } ?>\r\n            ]]></add>\r\n        </operation>\r\n    </file>\r\n    <file path=\"catalog/controller/common/footer.php\">\r\n        <operation>\r\n            <search>\r\n				<![CDATA[\r\n					$this->load->language(\'common/footer\');\r\n				]]>\r\n			</search>\r\n            <add position=\"before\"><![CDATA[\r\n				// BuyOneClick\r\n					$this->load->model(\'setting/setting\');\r\n					$current_language_id = $this->config->get(\'config_language_id\');\r\n					$data[\'buyoneclick_success_field\'] = htmlspecialchars_decode($this->config->get(\'buyoneclick_success_field_\'.$current_language_id));\r\n					$data[\'buyoneclick_status\'] = $this->config->get(\'buyoneclick_status\');\r\n					$data[\'buyoneclick_status_category\'] = $this->config->get(\'buyoneclick_status_category\');\r\n					$data[\'buyoneclick_field1_status\'] = $this->config->get(\'buyoneclick_field1_status\');\r\n					$data[\'buyoneclick_field1_required\'] = $this->config->get(\'buyoneclick_field1_required\');\r\n					$data[\'buyoneclick_field2_status\'] = $this->config->get(\'buyoneclick_field2_status\');\r\n					$data[\'buyoneclick_field2_required\'] = $this->config->get(\'buyoneclick_field2_required\');\r\n					$data[\'buyoneclick_field3_status\'] = $this->config->get(\'buyoneclick_field3_status\');\r\n					$data[\'buyoneclick_field3_required\'] = $this->config->get(\'buyoneclick_field3_required\');\r\n					$data[\'buyoneclick_field4_status\'] = $this->config->get(\'buyoneclick_field4_status\');\r\n					$data[\'buyoneclick_field4_required\'] = $this->config->get(\'buyoneclick_field4_required\');\r\n					$data[\'buyoneclick_validation_status\'] = $this->config->get(\'buyoneclick_validation_status\');\r\n					$data[\'buyoneclick_validation_type\'] = $this->config->get(\'buyoneclick_validation_type\');\r\n\r\n					$data[\'buyoneclick_admin_email\'] = $this->config->get(\'config_email\');\r\n\r\n					$this->load->language(\'module/buyoneclick\');\r\n					$data[\'buyoneclick_title\'] = $this->language->get(\'buyoneclick_title\');\r\n					$data[\'buyoneclick_button\'] = $this->language->get(\'buyoneclick_button\');\r\n					if ($data[\'buyoneclick_success_field\'] == \'\') {\r\n						$data[\'buyoneclick_success_field\'] = $this->language->get(\'buyoneclick_success\');\r\n					}\r\n					$data[\'buyoneclick_field1_title\'] = $this->language->get(\'buyoneclick_field1_title\');\r\n					$data[\'buyoneclick_field2_title\'] = $this->language->get(\'buyoneclick_field2_title\');\r\n					$data[\'buyoneclick_field3_title\'] = $this->language->get(\'buyoneclick_field3_title\');\r\n					$data[\'buyoneclick_field4_title\'] = $this->language->get(\'buyoneclick_field4_title\');\r\n					$data[\'buyoneclick_button_order\'] = $this->language->get(\'buyoneclick_button_order\');\r\n					$data[\'buyoneclick_required_text\'] = $this->language->get(\'buyoneclick_required_text\');\r\n					$data[\'buyoneclick_error_required\'] = $this->language->get(\'buyoneclick_error_required\');\r\n					$data[\'buyoneclick_error_sending\'] = $this->language->get(\'buyoneclick_error_sending\');\r\n\r\n					$data[\'buyoneclick_agree_status\'] = $this->config->get(\'buyoneclick_agree_status\');\r\n					if ($this->config->get(\'buyoneclick_agree_status\')) {\r\n						$this->load->model(\'catalog/information\');\r\n						$information_info = $this->model_catalog_information->getInformation($this->config->get(\'buyoneclick_agree_status\'));\r\n						if ($information_info) {\r\n							$data[\'buyoneclick_text_agree\'] = sprintf($this->language->get(\'buyoneclick_text_agree\'), $this->url->link(\'information/information/agree\', \'information_id=\' . $this->config->get(\'buyoneclick_agree_status\'), \'SSL\'), $information_info[\'title\'], $information_info[\'title\']);\r\n						} else {\r\n							$data[\'buyoneclick_text_agree\'] = \'\';\r\n						}\r\n					} else {\r\n						$data[\'buyoneclick_text_agree\'] = \'\';\r\n					}\r\n				// BuyOneClickEnd\r\n            ]]></add>\r\n        </operation>\r\n    </file>\r\n	<file path=\"catalog/view/theme/*/template/common/footer.tpl\">\r\n        <operation>\r\n            <search>\r\n				<![CDATA[\r\n					</body></html>\r\n				]]>\r\n			</search>\r\n            <add position=\"before\">\r\n				<![CDATA[\r\n				<?php if ($buyoneclick_status) { ?>\r\n					<div id=\"boc_order\" class=\"modal fade\">\r\n						<div class=\"modal-dialog\">\r\n							<div class=\"modal-content\">\r\n								<form id=\"boc_form\" action=\"\" role=\"form\">\r\n									<fieldset>\r\n								<div class=\"modal-header\">\r\n									<button class=\"close\" type